(()=>{const R=window.WIKI_CHARACTER_REVIEW,D=window.WIKI,S=window.WIKI_SKILLS;
for(const kind of ['sets','nodes','skills'])Object.assign(S[kind],R.added[kind]);
for(const c of [...D.lords,...D.characters]){const p=R.changes[c.id];if(p){Object.assign(c,p);if(p.skillSets?.length)S.characters[c.id]=p.skillSets;}}
for(const [id,a]of Object.entries(R.aliases)){const c=D.characters.find(c=>c.id===id),l=D.lords.find(l=>l.id===a.id);if(c&&l){(l.characterVariants??=[]).push(c);if(S.characters[c.id])S.characters[l.id]=[...new Set([...(S.characters[l.id]||[]),...S.characters[c.id]])];}}
D.heroes=D.characters.filter(c=>c.roleType==='hero'&&c.heroClass!=='ordinary');
})();
